import{_ as i,o as n,c as s,a2 as a}from"./chunks/framework.Uc5-6EiL.js";const u=JSON.parse('{"title":"10 - Debugging","description":"","frontmatter":{},"headers":[],"relativePath":"modul/10-debugging.md","filePath":"content/modul/10 - Debugging.md","lastUpdated":1786970474000}'),t={name:"modul/10-debugging.md"};function l(r,e,h,d,o,c){return n(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="_10-debugging" tabindex="-1">10 - Debugging <a class="header-anchor" href="#_10-debugging" aria-label="Permalink to &quot;10 - Debugging&quot;">​</a></h1><p>Beim Programmieren funktioniert etwas oft nicht beim ersten Versuch. Das ist normal. <strong>Debugging</strong> bedeutet, einen Fehler systematisch zu suchen, zu verstehen und zu beheben.</p><p>Der JavaScript-Goblin verändert die Webseite im Hintergrund. Wenn er unterwegs stolpert, hinterlässt er meistens Hinweise in der Browser-Konsole. Wir müssen diese Hinweise lesen und Schritt für Schritt herausfinden, wo das Problem liegt.</p><p>Den wichtigsten Debugging-Befehl findest du auch im Abschnitt <a href="./9-cheatsheet#debugging">Debugging</a> des Cheatsheets.</p><h2 id="bevor-du-nach-einem-fehler-suchst" tabindex="-1">Bevor du nach einem Fehler suchst <a class="header-anchor" href="#bevor-du-nach-einem-fehler-suchst" aria-label="Permalink to &quot;Bevor du nach einem Fehler suchst&quot;">​</a></h2><p>Prüfe zuerst die einfachen Dinge:</p><ol><li>Hast du alle Dateien gespeichert?</li><li>Hast du die Webseite neu geladen?</li><li>Bearbeitest du die richtige Datei und das richtige Projekt?</li><li>Ist <code>script.js</code> mit dem HTML verbunden?</li><li>Testest du wirklich die Interaktion, zum Beispiel mit einem Klick oder Tastendruck?</li></ol><p>Wenn das Problem danach noch besteht, öffnen wir die Konsole.</p><h2 id="die-browser-konsole-offnen" tabindex="-1">Die Browser-Konsole öffnen <a class="header-anchor" href="#die-browser-konsole-offnen" aria-label="Permalink to &quot;Die Browser-Konsole öffnen&quot;">​</a></h2><p>Die Konsole gehört zu den Entwicklerwerkzeugen des Browsers.</p><ul><li><strong>Chrome oder Edge unter Windows:</strong> Drücke <code>F12</code> oder <code>Ctrl + Shift + I</code>.</li><li><strong>Chrome auf dem Mac:</strong> Drücke <code>Cmd + Option + I</code>.</li><li>Wähle danach den Tab <strong>Console</strong>.</li></ul><p>Rote Meldungen sind Fehler. Gelbe Meldungen sind Warnungen. Beginne immer mit dem <strong>ersten roten Fehler</strong>, denn ein früher Fehler kann weitere Fehler verursachen.</p><h2 id="eine-fehlermeldung-lesen" tabindex="-1">Eine Fehlermeldung lesen <a class="header-anchor" href="#eine-fehlermeldung-lesen" aria-label="Permalink to &quot;Eine Fehlermeldung lesen&quot;">​</a></h2><p>Eine Fehlermeldung enthält meistens drei wichtige Hinweise:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Uncaught ReferenceError: scoreValue is not defined</span></span>\n<span class="line"><span>    at script.js:18</span></span></code></pre></div><ul><li><strong>Art des Fehlers:</strong> <code>ReferenceError</code></li><li><strong>Hinweis:</strong> <code>scoreValue is not defined</code></li><li><strong>Ort:</strong> <code>script.js</code>, Zeile <code>18</code></li></ul><p>Klicke in der Konsole auf <code>script.js:18</code>. Der Browser zeigt dir die betroffene Codezeile.</p><p>Lies die Meldung langsam. Du musst nicht jedes englische Wort verstehen. Der Name einer Variable, eine Datei und eine Zeilennummer reichen oft schon, um die richtige Stelle zu finden.</p><h2 id="mit-console-log-prufen-was-passiert" tabindex="-1">Mit <code>console.log(...)</code> prüfen, was passiert <a class="header-anchor" href="#mit-console-log-prufen-was-passiert" aria-label="Permalink to &quot;Mit `console.log(...)` prüfen, was passiert&quot;">​</a></h2><p>Mit <a href="./9-cheatsheet#debugging"><code>console.log(...)</code></a> kannst du Nachrichten und Werte in der Konsole anzeigen.</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;JavaScript wurde gestartet&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Erscheint die Nachricht nicht, wird diese Codezeile nicht ausgeführt. Prüfe dann, ob die richtige JavaScript-Datei eingebunden ist und ob vorher bereits ein Fehler passiert.</p><p>Du kannst auch den Wert einer Variable anzeigen:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Score:&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, scoreValue);</span></span></code></pre></div><p>Die Beschriftung <code>&quot;Score:&quot;</code> hilft dir, die Ausgabe später wiederzuerkennen.</p><h2 id="prufen-ob-ein-html-element-gefunden-wurde" tabindex="-1">Prüfen, ob ein HTML-Element gefunden wurde <a class="header-anchor" href="#prufen-ob-ein-html-element-gefunden-wurde" aria-label="Permalink to &quot;Prüfen, ob ein HTML-Element gefunden wurde&quot;">​</a></h2><p>Nach einem <code>querySelector(...)</code> kannst du das Ergebnis ausgeben:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> player </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> document.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">querySelector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#player&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Player:&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, player);</span></span></code></pre></div><p>Die Befehle <a href="./9-cheatsheet#variablen"><code>let</code></a> und <a href="./9-cheatsheet#html-elemente-auswahlen"><code>document.querySelector(...)</code></a> findest du ebenfalls im Cheatsheet.</p><p>Zeigt die Konsole das HTML-Element, wurde es gefunden. Zeigt sie <code>null</code>, passt der Selektor nicht zu deinem HTML. Prüfe dann:</p><ul><li>Beginnt eine ID im Selektor mit <code>#</code>?</li><li>Beginnt eine Klasse im Selektor mit <code>.</code>?</li><li>Ist der Name im HTML und im JavaScript genau gleich geschrieben?</li><li>Stimmen Gross- und Kleinschreibung?</li></ul><p><code>#Player</code> und <code>#player</code> sind für JavaScript nicht dasselbe.</p><h2 id="prufen-ob-ein-event-ausgefuhrt-wird" tabindex="-1">Prüfen, ob ein Event ausgeführt wird <a class="header-anchor" href="#prufen-ob-ein-event-ausgefuhrt-wird" aria-label="Permalink to &quot;Prüfen, ob ein Event ausgeführt wird&quot;">​</a></h2><p>Wenn bei einem Klick nichts passiert, setze eine Ausgabe direkt in den Event Listener:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">button.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addEventListener</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;click&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Button wurde angeklickt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>Den <a href="./9-cheatsheet#events"><code>addEventListener(...)</code></a> findest du im Cheatsheet.</p><ul><li>Erscheint die Nachricht, funktioniert das Event. Der Fehler liegt wahrscheinlich bei der Aktion danach.</li><li>Erscheint die Nachricht nicht, prüfe den ausgewählten Button und den Event Listener.</li></ul><p>Mit mehreren Ausgaben kannst du verfolgen, wie weit JavaScript kommt:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1: Datei gestartet&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">button.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addEventListener</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;click&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2: Klick erkannt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;3: Aktion startet&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>Die letzte sichtbare Nachricht zeigt dir, bis wohin der Code funktioniert.</p><h2 id="typische-fehlermeldungen" tabindex="-1">Typische Fehlermeldungen <a class="header-anchor" href="#typische-fehlermeldungen" aria-label="Permalink to &quot;Typische Fehlermeldungen&quot;">​</a></h2><h3 id="is-not-defined" tabindex="-1"><code>is not defined</code> <a class="header-anchor" href="#is-not-defined" aria-label="Permalink to &quot;`is not defined`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ReferenceError: scoreValue is not defined</span></span></code></pre></div><p>JavaScript kennt diesen Namen nicht. Prüfe:</p><ul><li>Wurde die Variable vorher mit <code>let</code> definiert?</li><li>Ist der Name überall genau gleich geschrieben?</li><li>Ist die Variable an dieser Stelle verfügbar?</li></ul><h3 id="cannot-read-properties-of-null" tabindex="-1"><code>Cannot read properties of null</code> <a class="header-anchor" href="#cannot-read-properties-of-null" aria-label="Permalink to &quot;`Cannot read properties of null`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TypeError: Cannot read properties of null</span></span></code></pre></div><p>Meistens hat <code>querySelector(...)</code> kein HTML-Element gefunden. Prüfe den Selektor und den Namen im HTML.</p><h3 id="unexpected-token" tabindex="-1"><code>Unexpected token</code> <a class="header-anchor" href="#unexpected-token" aria-label="Permalink to &quot;`Unexpected token`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SyntaxError: Unexpected token</span></span></code></pre></div><p>JavaScript kann den Code nicht lesen. Häufig fehlt kurz vor der markierten Stelle ein Zeichen. Prüfe:</p><ul><li>Sind alle runden Klammern <code>()</code> geschlossen?</li><li>Sind alle geschweiften Klammern <code>{}</code> geschlossen?</li><li>Sind Texte am Anfang und Ende mit Anführungszeichen geschrieben?</li></ul><h3 id="is-not-a-function" tabindex="-1"><code>is not a function</code> <a class="header-anchor" href="#is-not-a-function" aria-label="Permalink to &quot;`is not a function`&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TypeError: ... is not a function</span></span></code></pre></div><p>JavaScript versucht etwas wie eine Funktion aufzurufen. Prüfe den Funktionsnamen und seine Schreibweise. Vergleiche den Befehl mit dem <a href="./9-cheatsheet">Cheatsheet</a>.</p><h2 id="fehler-systematisch-eingrenzen" tabindex="-1">Fehler systematisch eingrenzen <a class="header-anchor" href="#fehler-systematisch-eingrenzen" aria-label="Permalink to &quot;Fehler systematisch eingrenzen&quot;">​</a></h2><p>Wenn du nicht weisst, wo der Fehler liegt, gehe immer gleich vor:</p><ol><li>Speichere alle Dateien und lade die Webseite neu.</li><li>Öffne die Konsole und lies den ersten roten Fehler.</li><li>Öffne die angezeigte Datei und Zeile.</li><li>Prüfe Namen, Klammern und Anführungszeichen.</li><li>Setze <code>console.log(...)</code> vor und nach die verdächtige Stelle.</li><li>Teste erneut und beobachte, welche Ausgaben erscheinen.</li><li>Vergleiche die verwendeten Befehle mit dem Cheatsheet.</li><li>Ändere nur eine Sache und teste danach erneut.</li></ol><p>So wird aus „Es funktioniert nicht“ eine genaue Frage wie:</p><blockquote><p>Der Klick wird erkannt, aber <code>player</code> ist <code>null</code>. Wahrscheinlich stimmt der Selektor nicht.</p></blockquote><p>Mit einer genauen Beobachtung kannst du selbst gezielter suchen und anderen besser erklären, wobei du Hilfe brauchst.</p><h2 id="nach-dem-debugging" tabindex="-1">Nach dem Debugging <a class="header-anchor" href="#nach-dem-debugging" aria-label="Permalink to &quot;Nach dem Debugging&quot;">​</a></h2><p>Entferne reine Testausgaben wieder, wenn dein Code funktioniert. Nützliche Ausgaben darfst du während der Entwicklung behalten, aber die Konsole sollte übersichtlich bleiben.</p><p>Merke:</p><blockquote><p>Nicht raten: speichern, Konsole öffnen, ersten Fehler lesen, Stelle prüfen und mit <code>console.log(...)</code> Schritt für Schritt eingrenzen.</p></blockquote>',65)])])}const g=i(t,[["render",l]]);export{u as __pageData,g as default};
